(()=>{
  'use strict';
  const BASE='https://woongbi-quote-api.woongbts.workers.dev';
  const rows={senior:[],value:[],premium:[]};
  const state={ready:false,error:false};
  // These identifiers were checked against the current public device and plan catalogs.
  // Prices are deliberately NOT hardcoded: the private quote API supplies current totals.
  const seniorDevices=[
    {d:{id:'SKT-XD-2824',carrier:'SKT',name:'갤럭시 A17 LTE',model_code:'SM-A175N'},
     p:{id:'SKT-XP-969',carrier:'SKT',name:'T플랜 세이브',monthly_fee:33000}},
    {d:{id:'LG-XD-2826',carrier:'LGU+',name:'갤럭시 A17 LTE',model_code:'SM-A175N'},
     p:{id:'LG-XP-2512',carrier:'LGU+',name:'데이터플랜1.5GB',monthly_fee:33000}}
  ];
  async function post(category){
    const ctl=typeof AbortController!=='undefined'?new AbortController():null;
    const t=ctl?setTimeout(()=>ctl.abort(),8000):0;
    try{
      const response=await fetch(BASE+'/recommend/purpose',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({category,carrier:'all',join_type:'번호이동',basic_pension:false}),signal:ctl?.signal});
      const data=await response.json().catch(()=>({}));
      if(!response.ok||data?.ok!==true)throw Error(data?.error||'recommend-unavailable');
      return(Array.isArray(data.items)?data.items:[]).map(item=>({...item,join:item.joinLabel||'번호이동'}));
    }finally{if(t)clearTimeout(t)}
  }
  async function quote(device,plan,method){
    const ctl=typeof AbortController!=='undefined'?new AbortController():null;
    const t=ctl?setTimeout(()=>ctl.abort(),8000):0;
    try{
      const response=await fetch(BASE+'/quote/mobile',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({device_id:device.id,plan_id:plan.id,join_type:'번호이동',method,months:24,welfare_type:'none'}),signal:ctl?.signal});
      if(!response.ok)throw Error('quote-'+response.status);
      const data=await response.json().catch(()=>({}));
      if(data?.ok!==true)throw Error('quote-unavailable');
      return data.quote||null;
    }finally{if(t)clearTimeout(t)}
  }
  async function seniorItem(item){
    const attempts=await Promise.allSettled([quote(item.d,item.p,'support'),quote(item.d,item.p,'contract')]);
    const options=attempts.map((x,i)=>x.status==='fulfilled'?{...x.value,method:i===0?'support':'contract'}:null)
      .filter(q=>q?.known&&Number.isFinite(Number(q.monthly))&&Number(q.monthly)>=0
        && Number(q.planFee)===33000);
    options.sort((a,b)=>Number(a.monthly)-Number(b.monthly));
    const best=options[0];
    return {...item,join:'번호이동',best:best?{method:best.method,monthly:Number(best.monthly)}:
      {method:'contract',monthly:null},quoteUnavailable:!best};
  }
  function detailUrl(item){
    const q=new URLSearchParams();
    item?.d?.carrier&&q.set('c',item.d.carrier);
    q.set('j',item?.join||item?.joinLabel||'번호이동');
    if(['support','contract'].includes(item?.best?.method))q.set('m',item.best.method);
    item?.d?.id&&q.set('d',item.d.id);
    item?.p?.id&&q.set('p',item.p.id);
    q.set('mo','24');q.set('w',item?.welfare||'none');
    return'/rates.html?'+q.toString();
  }
  const ready=Promise.all([
    Promise.all(seniorDevices.map(seniorItem)).then(x=>{rows.senior=x}),
    ...['value','premium'].map(category=>post(category).then(x=>{rows[category]=x}))
  ]).then(()=>{state.ready=true;document.documentElement.dataset.homeRecommendApi='ready';return rows})
    .catch(error=>{state.error=true;document.documentElement.dataset.homeRecommendApi='unavailable';throw error});
  window.WoongbiRecommendationV2={
    ready,status:()=>({ready:state.ready,error:state.error,source:'server'}),
    recommend:category=>rows[category]||[],detailUrl,dataDate:()=> '서버 최신값'
  };
})();
